def solve_sudoku(board):
    def valid(r, c, ch):
        box = 3 * (r // 3), 3 * (c // 3)
        for i in range(9):
            if board[r][i] == ch or board[i][c] == ch:
                return False
            if board[box[0] + i // 3][box[1] + i % 3] == ch:
                return False
        return True

    def backtrack():
        for r in range(9):
            for c in range(9):
                if board[r][c] == 0:
                    for ch in range(1, 10):
                        if valid(r, c, ch):
                            board[r][c] = ch
                            if backtrack():
                                return True
                            board[r][c] = 0
                    return False
        return True

    backtrack()
    return board

